-- Fiches détaillées des espèces : catégorie, description, semis, sol, entretien, ravageurs, récolte
alter table public.species
  add column category text check (category in ('legume-fruit','racine','bulbe','feuille','chou','tige','legumineuse','aromatique','fleur','petit-fruit','sol')),
  add column difficulty text check (difficulty in ('facile','moyen','exigeant')),
  add column sow_depth_cm numeric(3,1),
  add column germination_days int,
  add column description text,
  add column sowing text,
  add column soil text,
  add column care text,
  add column pests text,
  add column harvest_tips text;

comment on column public.species.sow_depth_cm is 'Profondeur de semis ou de plantation (cm)';
comment on column public.species.germination_days is 'Délai de levée (jours) ; null pour les plants et les vivaces';

update public.species set category='legume-fruit', difficulty='moyen', sow_depth_cm=0.5, germination_days=7, description='Reine du potager d''été : fruits charnus, rouges, jaunes ou noirs, à croquer ou à cuisiner.', sowing='Semis sous abri en mars-avril à 20 °C, repiquage en godet, plantation en mai après les Saints de glace en enterrant une partie de la tige.', soil='Sol riche, profond et bien drainé ; compost mûr à la plantation ; plein soleil.', care='Tuteurer, supprimer les gourmands, arroser au pied sans mouiller le feuillage, pailler pour garder la fraîcheur.', pests='Mildiou (taches brunes par temps humide), pucerons, aleurodes, noctuelles. Aérer et éviter les arrosages sur les feuilles.', harvest_tips='Cueillir bien colorée, de juillet aux premières gelées. À consommer en quelques jours ; éviter le réfrigérateur qui ternit le goût.' where slug='tomate';
update public.species set category='legume-fruit', difficulty='facile', sow_depth_cm=0.5, germination_days=7, description='Petits fruits sucrés en grappes, très productifs, idéaux pour l''apéritif.', sowing='Semis sous abri en mars-avril, plantation en mai après les Saints de glace.', soil='Sol riche et bien drainé ; plein soleil ; moins exigeante en eau que les grosses tomates.', care='Tuteur ou treillage, gourmands à pincer ; arrosage régulier pour éviter l''éclatement des fruits.', pests='Mildiou, pucerons, aleurodes. Aérer le feuillage et pailler.', harvest_tips='Cueillir au fil de l''été, de juillet à octobre ; les fruits se gardent quelques jours à température ambiante.' where slug='tomate-cerise';
update public.species set category='legume-fruit', difficulty='exigeant', sow_depth_cm=0.5, germination_days=10, description='Fruit croquant et doux, vert puis rouge, jaune ou orange en mûrissant.', sowing='Semis en février-mars sous abri chauffé (25 °C), plantation en mai-juin quand les nuits restent au-dessus de 12 °C.', soil='Sol riche, léger et chaud ; place très ensoleillée et abritée du vent.', care='Arrosage régulier sans excès, paillage, léger tuteurage ; pincer la première fleur pour renforcer la plante.', pests='Pucerons, acariens (araignées rouges), pourriture apicale en cas d''arrosage irrégulier.', harvest_tips='Cueillir vert dès que le fruit est ferme, ou plus tard pour la couleur et la douceur. Se garde 1 à 2 semaines au frais.' where slug='poivron';
update public.species set category='legume-fruit', difficulty='moyen', sow_depth_cm=0.5, germination_days=10, description='Fruit piquant, du doux au très fort, qui se sèche et se conserve très bien.', sowing='Semis en février-mars sous abri chauffé, plantation en mai-juin une fois le risque de gel passé.', soil='Sol léger, riche et bien drainé ; plein soleil et chaleur.', care='Arroser au pied avec modération, pailler ; un petit tuteur si les fruits sont lourds.', pests='Pucerons, aleurodes, acariens. Surveiller le dessous des feuilles.', harvest_tips='Cueillir à maturité (rouge, jaune ou orangé selon la variété) ; se sèche en chapelet ou se congèle. Gants conseillés pour les variétés fortes.' where slug='piment';
update public.species set category='legume-fruit', difficulty='exigeant', sow_depth_cm=0.5, germination_days=10, description='Fruit violet à chair fondante, très sensible au froid.', sowing='Semis en février-mars à 22-25 °C, repiquage, plantation en mai-juin seulement quand le sol est bien réchauffé.', soil='Sol riche, meuble, frais mais drainé ; exposition chaude et abritée.', care='Arrosage régulier, paillage, tuteur ; limiter à 4-5 fruits par pied pour un bon calibre.', pests='Doryphores (à ramasser à la main), pucerons, acariens, altises.', harvest_tips='Cueillir quand la peau est brillante et tendre, avant que les graines ne durcissent. Se garde 1 semaine au frais.' where slug='aubergine';
update public.species set category='legume-fruit', difficulty='facile', sow_depth_cm=2, germination_days=6, description='Très productive : fruits allongés à cueillir jeunes, fleurs comestibles.', sowing='Semis en avril-mai en godet sous abri, ou en place dès mai ; plantation fin mai.', soil='Sol riche en matière organique, frais ; plein soleil ; prévoir de la place.', care='Arrosages copieux au pied, paillage ; cueillir souvent pour relancer la production.', pests='Oïdium (feutrage blanc), pucerons, limaces sur les jeunes plants. Arroser sans mouiller le feuillage.', harvest_tips='Cueillir à 15-20 cm, tous les 2-3 jours, de juillet à septembre. Se garde 4-5 jours au frais.' where slug='courgette';
update public.species set category='legume-fruit', difficulty='moyen', sow_depth_cm=1.5, germination_days=6, description='Fruit frais et croquant, à faire grimper pour gagner de la place.', sowing='Semis en avril sous abri, plantation en mai-juin à l''abri du froid ; semis en place possible dès fin mai.', soil='Sol riche, frais et meuble ; chaleur et soleil, mais sans manque d''eau.', care='Palisser sur un treillage, arroser abondamment au pied, pailler ; pincer au-dessus de la 5e feuille.', pests='Oïdium, pucerons, acariens. Aérer et éviter l''excès d''humidité sur le feuillage.', harvest_tips='Cueillir jeune et ferme avant qu''il ne jaunisse, de juillet à septembre. Se garde 1 semaine au frais.' where slug='concombre';
update public.species set category='legume-fruit', difficulty='facile', sow_depth_cm=3, germination_days=7, description='Grosse coureuse qui se conserve tout l''hiver : potimarron, butternut, potiron…', sowing='Semis en avril-mai en godet sous abri, plantation fin mai ; ou semis direct en mai-juin.', soil='Sol très riche (compost, fumier mûr), frais ; plein soleil ; beaucoup de place.', care='Arroser copieusement au pied, pailler ; limiter à 2-3 fruits par pied ; laisser courir ou palisser.', pests='Oïdium, pucerons, limaces. Poser les fruits sur une planche ou de la paille.', harvest_tips='Récolter à maturité complète (pédoncule sec, peau dure) avant les gelées, en septembre-octobre. Se conserve plusieurs mois au sec, à 10-15 °C.' where slug='courge';
update public.species set category='legume-fruit', difficulty='exigeant', sow_depth_cm=2, germination_days=7, description='Fruit sucré et parfumé, qui demande chaleur et soleil.', sowing='Semis en avril sous abri chauffé, plantation fin mai-juin sur sol bien réchauffé, idéalement sous tunnel ou cloche.', soil='Sol riche, léger et chaud ; exposition très ensoleillée et abritée.', care='Arroser au pied sans excès à l''approche de la maturité, pailler, pincer les tiges après 2-3 fruits.', pests='Oïdium, pucerons, limaces. Éviter de mouiller le feuillage.', harvest_tips='Mûr quand il dégage un parfum sucré et que le pédoncule se fendille, en août-septembre. À consommer dans la semaine.' where slug='melon';
update public.species set category='legume-fruit', difficulty='exigeant', sow_depth_cm=2, germination_days=7, description='Fruit géant et désaltérant, pour les étés chauds.', sowing='Semis en avril-mai sous abri chauffé, plantation en juin dans un sol bien chaud.', soil='Sol léger, riche et chaud, bien drainé ; plein soleil ; beaucoup de place.', care='Arroser régulièrement, pailler, limiter à 2-3 fruits par pied ; poser les fruits sur une planche.', pests='Oïdium, pucerons, limaces. Surveiller par temps humide.', harvest_tips='Mûre quand la vrille près du pédoncule se dessèche et que le son est mat, en août-septembre. Se garde 1 à 2 semaines au frais.' where slug='pasteque';
update public.species set category='legumineuse', difficulty='facile', sow_depth_cm=3, germination_days=8, description='Épis sucrés à croquer, qui servent aussi de tuteur aux haricots.', sowing='Semis en place en mai-juin, 2-3 graines par poquet ; planter en carré (plusieurs rangs) pour la pollinisation.', soil='Sol riche, profond et frais ; plein soleil.', care='Butter à 30 cm, arroser à la floraison, apporter du compost.', pests='Pyrale, corbeaux (qui déterrent les graines), limaces sur les jeunes plants.', harvest_tips='Cueillir quand les soies sont brunes et que le grain laisse un liquide laiteux sous l''ongle, en août-septembre. À consommer le jour même pour garder le sucre.' where slug='mais';
update public.species set category='legumineuse', difficulty='facile', sow_depth_cm=3, germination_days=8, description='Haricot sans rames, productif, à cueillir en vert ou à écosser.', sowing='Semis en place de mai à juillet, à 3 cm, quand le sol atteint 12 °C ; échelonner les semis.', soil='Sol léger, meuble, pas trop riche ; plein soleil.', care='Butter légèrement, arroser à la floraison, cueillir souvent pour prolonger la récolte.', pests='Pucerons noirs, limaces, rouille. Ne pas travailler les plants mouillés.', harvest_tips='Cueillir les gousses tendres de juillet à septembre ; se congèle bien.' where slug='haricot-nain';
update public.species set category='legumineuse', difficulty='facile', sow_depth_cm=3, germination_days=8, description='Variété grimpante, plus productive que le haricot nain sur peu de place.', sowing='Semis en place de mai à juin, en poquets au pied des rames.', soil='Sol léger, meuble, pas trop riche ; plein soleil.', care='Tuteurer (rames ou filet), arroser à la floraison, cueillir régulièrement.', pests='Pucerons noirs, limaces, rouille.', harvest_tips='Cueillir régulièrement jusqu''aux premières gelées ; se congèle bien.' where slug='haricot-a-rames';
update public.species set category='legumineuse', difficulty='facile', sow_depth_cm=3, germination_days=10, description='Légume de printemps sucré, à écosser.', sowing='Semis en place de février à avril, à 3 cm, en rangs doubles.', soil='Sol frais et meuble, sans fumure fraîche ; soleil ou mi-ombre.', care='Rames ou filet pour grimper, arrosage régulier à la floraison.', pests='Pucerons verts, tordeuse du pois, oiseaux sur les jeunes semis.', harvest_tips='Écosser quand les cosses sont bien remplies, de mai à juillet ; à consommer vite ou à congeler.' where slug='petit-pois';
update public.species set category='legumineuse', difficulty='facile', sow_depth_cm=5, germination_days=14, description='Légumineuse rustique qui enrichit le sol en azote.', sowing='Semis en place en octobre-novembre ou de février à avril, à 5 cm.', soil='Sol profond et frais ; soleil ; supporte bien le froid.', care='Pincer le sommet à la floraison contre les pucerons ; tuteurer si besoin.', pests='Pucerons noirs, bruches ; peu de maladies.', harvest_tips='Cueillir les cosses de mai à juillet ; se mange fraîche ou séchée.' where slug='feve';
update public.species set category='racine', difficulty='moyen', sow_depth_cm=1, germination_days=14, description='Racine orange croquante, à semer en place.', sowing='Semis en place de mars à juillet, en rangs espacés de 25 cm ; éclaircir à 4 cm. Levée lente (2 à 3 semaines).', soil='Sol profond, meuble, sans cailloux ni fumier frais ; plein soleil.', care='Garder la terre humide jusqu''à la levée, éclaircir, biner ; butter si les collets verdissent.', pests='Mouche de la carotte (voile anti-insectes), nématodes. L''association avec le poireau la protège.', harvest_tips='Arracher de juin à novembre selon le semis. Se garde plusieurs mois en cave, dans du sable humide.' where slug='carotte';
update public.species set category='racine', difficulty='facile', sow_depth_cm=1, germination_days=4, description='Le plus rapide des légumes : prêt en 4 semaines.', sowing='Semis en place de mars à septembre, en lignes ; échelonner tous les 15 jours.', soil='Sol frais et meuble ; mi-ombre en été pour éviter la montée à graines.', care='Arroser régulièrement pour des racines tendres, éclaircir à 3 cm.', pests='Altises (petits trous dans les feuilles) : voile anti-insectes et arrosages réguliers.', harvest_tips='Cueillir dès que la racine est grosse comme une bille : plus tard elle devient creuse et piquante. À consommer dans la semaine.' where slug='radis';
update public.species set category='racine', difficulty='facile', sow_depth_cm=2, germination_days=7, description='Racine sucrée, rouge ou rose, aussi bonne en salade qu''en soupe.', sowing='Semis en place d''avril à juillet, à 1-2 cm ; éclaircir à 10 cm.', soil='Sol profond et meuble, sans fumure fraîche.', care='Biner, arroser en période sèche, éclaircir quand les plants ont 4 feuilles.', pests='Pucerons noirs, cercosporiose (taches sur les feuilles). Rotation de 3 ans.', harvest_tips='Arracher à 5-8 cm de diamètre de juillet à octobre. Se garde plusieurs semaines au frais, feuilles coupées.' where slug='betterave';
update public.species set category='racine', difficulty='facile', sow_depth_cm=1, germination_days=5, description='Racine douce, à récolter jeune au printemps ou à l''automne.', sowing='Semis en place en mars-avril puis d''août à septembre ; éclaircir à 10 cm.', soil='Sol frais et léger ; mi-ombre en été.', care='Arrosage régulier, éclaircissage, binage.', pests='Altises, mouche du chou, hernie du chou : voile anti-insectes et rotation.', harvest_tips='Cueillir quand la racine a la taille d''une balle de tennis. Se garde 1 à 2 semaines au frais.' where slug='navet';
update public.species set category='racine', difficulty='moyen', sow_depth_cm=1.5, germination_days=21, description='Racine ancienne à saveur douce et noisettée, résistante au gel.', sowing='Semis en place de mars à mai ; levée lente (3 semaines) : marquer le rang avec des radis.', soil='Sol profond et meuble, sans cailloux ; plein soleil.', care='Éclaircir à 10 cm, biner, arroser en période sèche.', pests='Mouche de la carotte, chancre. Rotation de 3-4 ans.', harvest_tips='Arracher d''octobre à février : le gel améliore le goût. Se garde longtemps en terre ou en cave.' where slug='panais';
update public.species set category='racine', difficulty='exigeant', sow_depth_cm=0.5, germination_days=15, description='Grosse racine au goût de céleri, pour soupes et salades.', sowing='Semis en février-mars sous abri chauffé ; plantation en mai en laissant le collet à fleur de terre.', soil='Sol riche, frais et humifère ; plein soleil ou mi-ombre.', care='Arroser généreusement, pailler, retirer les radicelles latérales du collet.', pests='Mouche du céleri, rouille, septoriose. Aérer.', harvest_tips='Arracher de septembre à novembre avant les fortes gelées. Se conserve plusieurs mois en cave.' where slug='celeri-rave';
update public.species set category='racine', difficulty='facile', sow_depth_cm=10, germination_days=null, description='Tubercule de base, aux nombreuses variétés précoces ou de garde.', sowing='Planter des plants germés de mars à mai, à 10 cm de profondeur, yeux vers le haut, tous les 35 cm.', soil='Sol meuble, profond et frais ; pas de fumier frais ; plein soleil.', care='Butter 2 fois (à 15 et 30 cm) pour éviter le verdissement et augmenter la récolte ; arroser en période sèche.', pests='Mildiou (humidité), doryphores (ramassage à la main), taupins. Rotation de 4 ans.', harvest_tips='Arracher quand le feuillage jaunit, de juin à septembre. Laisser sécher à l''ombre avant de stocker à la cave, à l''obscurité.' where slug='pomme-de-terre';
update public.species set category='racine', difficulty='facile', sow_depth_cm=10, germination_days=null, description='Tubercule vivace très rustique, à saveur d''artichaut.', sowing='Planter les tubercules de février à avril, à 10 cm, tous les 40 cm.', soil='Tous sols, même pauvres ; soleil ; plante envahissante à isoler.', care='Presque aucun entretien ; butter un peu ; couper les tiges en fin d''été si besoin.', pests='Peu sensible ; limaces sur les jeunes pousses.', harvest_tips='Arracher à la demande d''octobre à mars ; se conserve mal hors de terre (quelques jours).' where slug='topinambour';
update public.species set category='bulbe', difficulty='facile', sow_depth_cm=3, germination_days=null, description='Bulbe à gousses, aromatique et protecteur de nombreux voisins.', sowing='Planter les gousses pointe en haut à 3 cm de profondeur, d''octobre à novembre ou de février à mars.', soil='Sol léger et drainé ; plein soleil ; pas de fumure fraîche.', care='Désherber ; arrêter l''arrosage un mois avant la récolte.', pests='Rouille, pourriture blanche. Rotation de 4 ans.', harvest_tips='Arracher quand les feuilles jaunissent (juin-juillet) ; sécher au soleil puis tresser. Se garde jusqu''à 8 mois au sec.' where slug='ail';
update public.species set category='bulbe', difficulty='facile', sow_depth_cm=2, germination_days=null, description='Bulbe indispensable en cuisine, à planter en bulbilles ou à semer.', sowing='Planter des bulbilles de mars à avril, à 2 cm, ou semer en février-mars.', soil='Sol léger, riche et bien drainé ; soleil.', care='Désherber soigneusement ; arrêter l''arrosage en juillet.', pests='Mouche de l''oignon, mildiou, pourriture du collet. Voile anti-insectes.', harvest_tips='Arracher quand les feuilles se couchent (juillet-août) ; sécher 2 semaines. Se garde jusqu''au printemps.' where slug='oignon';
update public.species set category='bulbe', difficulty='facile', sow_depth_cm=2, germination_days=null, description='Plus fine que l''oignon, indispensable aux sauces.', sowing='Planter les bulbes de février à mars (ou à l''automne en terre légère), la pointe affleurant.', soil='Sol léger et drainé ; soleil.', care='Désherber, arroser peu ; chaque bulbe donne plusieurs échalotes.', pests='Mouche de l''oignon, rouille. Rotation de 4 ans.', harvest_tips='Arracher en juillet quand les feuilles jaunissent ; sécher au soleil. Se garde jusqu''à 8 mois.' where slug='echalote';
update public.species set category='bulbe', difficulty='facile', sow_depth_cm=2, germination_days=10, description='Légume d''hiver rustique, qu''on récolte à la demande.', sowing='Semis en pépinière de février à avril ; repiquer en juin-juillet dans des trous de 15 cm.', soil='Sol riche, frais et profond ; soleil.', care='Arroser régulièrement, butter pour blanchir le fût.', pests='Teigne du poireau, rouille, mouche mineuse. Voile anti-insectes.', harvest_tips='Arracher à la demande de septembre à mars. Résiste au gel.' where slug='poireau';
update public.species set category='feuille', difficulty='facile', sow_depth_cm=0.5, germination_days=4, description='Laitues et batavias à croquer, à échelonner.', sowing='Semis en place ou en godet de mars à août ; repiquer tous les 30 cm ; échelonner tous les 15 jours.', soil='Sol frais et riche ; mi-ombre l''été pour éviter la montée à graines.', care='Arroser souvent et peu à la fois ; pailler ; protéger des limaces.', pests='Limaces, pucerons, mildiou. Surveiller après la pluie.', harvest_tips='Couper à la base quand la pomme est formée ; à consommer rapidement.' where slug='salade';
update public.species set category='feuille', difficulty='facile', sow_depth_cm=1, germination_days=10, description='Petite salade d''hiver qui ne craint pas le gel.', sowing='Semis en place d''août à octobre, en lignes ou à la volée ; tasser légèrement le sol après le semis.', soil='Sol frais, plutôt tassé ; mi-ombre.', care='Arroser en période sèche, désherber.', pests='Limaces, oïdium. Peu exigeante.', harvest_tips='Cueillir rosette par rosette d''octobre à mars.' where slug='mache';
update public.species set category='feuille', difficulty='facile', sow_depth_cm=2, germination_days=8, description='Feuilles tendres riches en fer, à cultiver au frais.', sowing='Semis en place en mars-avril et d''août à octobre ; l''été il monte à graines.', soil='Sol riche et frais ; mi-ombre.', care='Arroser régulièrement ; désherber.', pests='Mildiou, limaces, pucerons. Choisir des variétés résistantes.', harvest_tips='Cueillir les feuilles extérieures ou couper la plante, 6 à 8 semaines après le semis.' where slug='epinard';
update public.species set category='feuille', difficulty='facile', sow_depth_cm=2, germination_days=7, description='Feuilles et côtes tendres, productives toute la saison.', sowing='Semis en place d''avril à juillet ; éclaircir à 30 cm.', soil='Sol riche et frais ; soleil ou mi-ombre.', care='Arroser régulièrement, pailler ; couper les feuilles à la base pour relancer la pousse.', pests='Pucerons, mineuse de la betterave, limaces.', harvest_tips='Couper les feuilles extérieures, de juillet à novembre. Se garde 3 jours au frais.' where slug='blette';
update public.species set category='feuille', difficulty='facile', sow_depth_cm=1, germination_days=4, description='Feuilles piquantes à croissance éclair.', sowing='Semis en place de mars à septembre, tous les 15 jours.', soil='Sol frais ; mi-ombre l''été.', care='Arroser souvent ; la chaleur la fait monter à graines.', pests='Altises : voile anti-insectes.', harvest_tips='Cueillir les feuilles dès 4 semaines ; plus elle grandit, plus elle est forte.' where slug='roquette';
update public.species set category='feuille', difficulty='facile', sow_depth_cm=1, germination_days=10, description='Vivace acidulée, parfaite en soupe ou en sauce.', sowing='Semis de mars à mai ou division de touffes ; éclaircir à 30 cm.', soil='Sol frais et humifère ; mi-ombre.', care='Couper les hampes florales ; diviser les touffes tous les 3-4 ans.', pests='Pucerons, rouille, limaces.', harvest_tips='Cueillir les jeunes feuilles d''avril à octobre.' where slug='oseille';
update public.species set category='chou', difficulty='moyen', sow_depth_cm=1, germination_days=7, description='Chou pommé : cabus, rouge ou frisé, du printemps à l''hiver.', sowing='Semis en pépinière d''avril à mai ; plantation de mai à juillet, en enterrant jusqu''aux premières feuilles.', soil='Sol riche, frais, plutôt argileux ; plein soleil.', care='Arroser régulièrement, butter, couvrir d''un filet contre la piéride.', pests='Piéride et noctuelle (chenilles), altises, hernie du chou. Filet anti-insectes ; rotation de 4 ans.', harvest_tips='Couper la pomme quand elle est ferme, d''août à décembre. Se garde 1 à 2 mois au frais.' where slug='chou';
update public.species set category='chou', difficulty='moyen', sow_depth_cm=1, germination_days=7, description='Pommes vertes riches en vitamines, avec repousses latérales.', sowing='Semis en pépinière d''avril à mai ; plantation de mai à juillet.', soil='Sol riche et frais ; soleil.', care='Arrosage régulier, butter, filet anti-piéride.', pests='Piéride, altise, hernie du chou. Filet ; rotation de 4 ans.', harvest_tips='Couper la tête centrale avant l''ouverture des fleurs ; les rejets suivent.' where slug='brocoli';
update public.species set category='chou', difficulty='exigeant', sow_depth_cm=1, germination_days=7, description='Pomme blanche, plus exigeante en eau et en fraîcheur.', sowing='Semis en pépinière de mars à mai ; plantation de mai à juillet.', soil='Sol riche, frais et bien drainé.', care='Arrosage régulier ; protéger la pomme du soleil en repliant les feuilles.', pests='Piéride, altise, mouche du chou. Filet ; rotation de 4 ans.', harvest_tips='Couper quand la pomme est ferme et blanche, de septembre à novembre.' where slug='chou-fleur';
